\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
trig format plots=rad,
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={line width=0.8pt, color=black},
axis line style = thick,
axis y line = center,
axis x line = middle,
%axis equal,
%grid = both,
xmin = -5.5,
xmax = 2,
ymin = -3,
ymax = 4,
xtick = {-4,-2},
ytick = {2},
xlabel style={below right},
		ylabel style={above right},
		%% Here, we can control the positioning of each individual tick.
		x tick label style={xshift={(\tick==-2)*5pt}},
		%x tick label style={xshift={(\tick==-2)*-2pt}},
		%x tick label style={xshift={(\tick==3)*4pt}},
		y tick label style={yshift={(\tick==9)*-3pt}},
		every axis x label/.style={
			at={(ticklabel* cs:1.02)},
			anchor=west,
		},
		every axis y label/.style={
			at={(ticklabel* cs:1.02)},
			anchor=south,
		}
		]


% Graphic
\addplot [domain=-7:5,samples=200,color=red,line width=1pt]{1/8*(x+4)*(x+2)^2};

% Labels


\end{axis}

\end{tikzpicture}
\end{document}

